// bs=32 intra prediction WITH neighbour availability, vs the software
// reference over all 13 modes and both availability combos. Validates the
// TX_32X32 predictor lane (directional core + non-directional core + the
// sm_weights_32 smooth table + DC) that HarborIntraReconWalk(maxLog2:3) uses.
// Kept in its own file (build is heavy) with a generous timeout.
void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  const bs = 32;
  test(
    'HarborIntraPredAvail bs=32 matches predictIntraRaw',
    timeout: const Timeout(Duration(minutes: 20)),
    () async {
      final t = HarborIntraPredAvail(bs: bs);
      final clk = SimpleClockGenerator(10).clk;
      final mode = Logic(name: 'mode', width: 4);
      final haveA = Logic(name: 'have_above');
      final haveL = Logic(name: 'have_left');
      final above = Logic(name: 'above', width: bs * 8);
      final left = Logic(name: 'left', width: bs * 8);
      final corner = Logic(name: 'above_left', width: 8);
      t.input('mode').srcConnection! <= mode;
      t.input('have_above').srcConnection! <= haveA;
      t.input('have_left').srcConnection! <= haveL;
      t.input('above').srcConnection! <= above;
      t.input('left').srcConnection! <= left;
      t.input('above_left').srcConnection! <= corner;
      await t.build();
      Simulator.setMaxSimTime(200000000);
      unawaited(Simulator.run());

      BigInt packB(List<int> b) {
        var v = BigInt.zero;
        for (var i = 0; i < b.length; i++) {
          v |= BigInt.from(b[i] & 0xff) << (i * 8);
        }
        return v;
      }

      final rng = Random(0x320A1);
      var gi = 0;
      for (var iter = 0; iter < 6; iter++) {
        final av = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final lf = [for (var i = 0; i < bs; i++) rng.nextInt(256)];
        final cr = rng.nextInt(256);
        for (var m = 0; m < 13; m++) {
          for (final combo in const [
            [1, 1],
            [1, 0],
            [0, 1],
            [0, 0],
          ]) {
            final av0 = combo[0], lv0 = combo[1];
            mode.put(m);
            haveA.put(av0);
            haveL.put(lv0);
            above.put(packB(av));
            left.put(packB(lf));
            corner.put(cr);
            await clk.nextPosedge;

            final want = _gold[gi++];
            final pv = t.output('pred').value.toBigInt();
            final got = [
              for (var p = 0; p < bs * bs; p++)
                ((pv >> (p * 8)) & BigInt.from(0xff)).toInt(),
            ];
            expect(
              got,
              equals(want),
              reason: 'bs=$bs mode=$m haveA=$av0 haveL=$lv0 iter=$iter',
            );
          }
        }
      }
      await Simulator.endSimulation();
    },
  );
}
